import React, { ElementType, forwardRef, ReactElement } from 'react';

import { ActionButtonOwnProps } from './action-group/ActionButton.js';
import { ActionGroup } from './action-group/ActionGroup.js';
import { PolymorphicComponentProps } from '../../core/types/polymorph.js';

// #region Typings
export type AppHeaderActionButtonOwnProps = Omit<ActionButtonOwnProps, 'pin'>;

export type AppHeaderActionButtonProps<E extends ElementType> =
  PolymorphicComponentProps<E, AppHeaderActionButtonOwnProps>;
// #endregion

/**
 * An action button used in the AppHeader actions menu.
 */
export const ActionButton: <E extends ElementType = 'button'>(
  props: AppHeaderActionButtonProps<E>,
) => ReactElement | null = forwardRef(
  <E extends ElementType>(
    props: AppHeaderActionButtonProps<E>,
    forwardedRef: typeof props.ref,
  ) => <ActionGroup.ActionButton ref={forwardedRef} {...props} />,
);

(ActionButton as typeof ActionButton & { displayName: string }).displayName =
  'AppHeader.Button';
